<?php declare(strict_types=1);
namespace DoubleYoupi\Modules\MediaLibrary;

use DoubleYoupi\Core\AbstractModule;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Automatically fills the alt text and title of an attachment
 * from its filename at upload time.
 *
 * Never overwrites a value entered manually by the user.
 * Only applies when the field is empty or contains the value
 * auto-generated by WordPress (filename without extension).
 */
class MetadataAutoFiller extends AbstractModule {

	public function id(): string {
		return 'media-library-metadata';
	}

	public function name(): string {
		return 'Refined Media Library — Metadata Auto-filler';
	}

	public function boot(): void {
		add_action( 'add_attachment', [ $this, 'on_add_attachment' ], 10, 1 );
	}

	public function on_add_attachment( int $post_id ): void {
		if ( ! Settings::auto_metadata_enabled() ) {
			return;
		}

		$filepath = get_attached_file( $post_id );
		if ( ! $filepath ) {
			return;
		}

		$filename = basename( $filepath );
		$post     = get_post( $post_id );
		if ( ! $post ) {
			return;
		}

		$parsed_title = FilenameParser::for_title( $filename );
		$parsed_alt   = FilenameParser::for_alt( $filename );

		// Title: replace only when empty or identical to the raw name without extension.
		// WP 6.4+ automatically derives a title from the filename (dashes → spaces,
		// first letter capitalised). We compare against the raw name without extension
		// to avoid overwriting the WP auto-value when it would produce the same result,
		// while still not overwriting a value entered manually by the user.
		$raw_name = pathinfo( $filename, PATHINFO_FILENAME );
		if ( $post->post_title === '' || $post->post_title === $raw_name ) {
			wp_update_post( [
				'ID'         => $post_id,
				'post_title' => $parsed_title,
			] );
		}

		// Alt text: fill only when completely absent.
		$current_alt = get_post_meta( $post_id, '_wp_attachment_image_alt', true );
		if ( $current_alt === '' || $current_alt === false ) {
			update_post_meta( $post_id, '_wp_attachment_image_alt', $parsed_alt );
		}
	}
}
